<?php require '../includes/functions.php';require_login();$u=$_SESSION['user'];if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['cancel'])){check_csrf();db()->prepare("UPDATE bookings SET status='cancelled' WHERE id=? AND user_id=? AND status='confirmed'")->execute([(int)$_POST['cancel'],$u['id']]);flash('success','Booking cancelled.');redirect('/movie-booking/user/dashboard.php');}$q=db()->prepare('SELECT b.*,m.title,s.show_date,s.show_time FROM bookings b JOIN shows s ON s.id=b.show_id JOIN movies m ON m.id=s.movie_id WHERE b.user_id=? ORDER BY b.created_at DESC');$q->execute([$u['id']]);$pageTitle='My dashboard';require '../includes/header.php';?>
<div class="container py-5"><h1>Hi, <?=e($u['name'])?></h1><p class="text-secondary">Your upcoming shows and booking history.</p><div class="booking-panel"><h4>Bookings</h4><div class="table-responsive"><table class="table table-dark table-hover align-middle"><thead><tr><th>Movie</th><th>Showtime</th><th>Code</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($q as $b):?><tr><td><?=e($b['title'])?></td><td><?=date('d M, g:i A',strtotime($b['show_date'].' '.$b['show_time']))?></td><td><?=e($b['booking_code'])?></td><td><span class="badge bg-<?=$b['status']==='confirmed'?'success':'secondary'?>"><?=e($b['status'])?></span></td><td><?php if($b['status']==='confirmed'):?><a class="btn btn-sm btn-outline-light" href="/movie-booking/ticket.php?id=<?=$b['id']?>">Ticket</a> <form class="d-inline" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><button name="cancel" value="<?=$b['id']?>" class="btn btn-sm btn-outline-danger" onclick="return confirm('Cancel this booking?')">Cancel</button></form><?php endif?></td></tr><?php endforeach?></tbody></table></div></div></div><?php require '../includes/footer.php'; ?>
